import{_ as o,o as s,c as r,a2 as n}from"./chunks/framework.Zh78JZbW.js";const p=JSON.parse('{"title":"Jouer en multijoueur","description":"","frontmatter":{},"headers":[],"relativePath":"guide/jouer.md","filePath":"guide/jouer.md"}'),t={name:"guide/jouer.md"};function u(i,e,a,l,c,d){return s(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="jouer-en-multijoueur" tabindex="-1">Jouer en multijoueur <a class="header-anchor" href="#jouer-en-multijoueur" aria-label="Permalink to &quot;Jouer en multijoueur&quot;">​</a></h1><p>Depuis l&#39;accueil, sélectionnez votre instance dans le menu situé sous le bouton, puis cliquez sur <strong>Jouer</strong>. Depuis la page d&#39;une instance, utilisez le bouton <strong>Lancer Minecraft</strong>.</p><h2 id="reseau-local-et-serveurs" tabindex="-1">Réseau local et serveurs <a class="header-anchor" href="#reseau-local-et-serveurs" aria-label="Permalink to &quot;Réseau local et serveurs&quot;">​</a></h2><ul><li><strong>Réseau local</strong> : l&#39;hôte ouvre son monde, puis Échap → <strong>Ouvrir au réseau local</strong>. Les autres joueurs le voient dans l&#39;onglet Multijoueur.</li><li><strong>Par Internet, sans serveur</strong> : voir <a href="./jouer-ensemble">Jouer ensemble</a>. Votre ami ouvre son monde, vous le rejoignez en un clic depuis Kodus.</li><li><strong>Serveur</strong> : Multijoueur → <strong>Ajouter un serveur</strong> → saisissez son adresse.</li><li><strong>Goupil SMP</strong>, le serveur officiel de Kodus, est ajouté automatiquement en tête de la liste Multijoueur de toutes vos instances. Si son adresse change, Kodus la met à jour au lancement suivant.</li></ul><h2 id="rejoindre-le-goupil-smp" tabindex="-1">Rejoindre le Goupil SMP <a class="header-anchor" href="#rejoindre-le-goupil-smp" aria-label="Permalink to &quot;Rejoindre le Goupil SMP&quot;">​</a></h2><p>Quand le Goupil SMP est ouvert, le bouton de l&#39;accueil est coupé en deux : <strong>Jouer</strong> à gauche, <strong>Rejoindre</strong> à droite. <strong>Rejoindre</strong> lance Minecraft directement connecté au serveur, sans passer par le menu Multijoueur. Deux choix s&#39;affichent :</p><ul><li><strong>Avec mon instance</strong> : l&#39;instance sélectionnée sous le bouton ;</li><li><strong>Avec l&#39;instance recommandée</strong> : l&#39;instance conseillée par l&#39;équipe du Goupil SMP (bonne version, mods d&#39;optimisation…). Kodus la crée au premier clic, puis la réutilise et la complète si l&#39;équipe ajoute des mods.</li></ul><p>Si l&#39;équipe ne recommande pas d&#39;instance, <strong>Rejoindre</strong> utilise directement la vôtre.</p><div class="tip custom-block"><p class="custom-block-title">Condition indispensable</p><p>Pour rejoindre un autre joueur, il faut la <strong>même version</strong> de Minecraft, le <strong>même loader</strong> et les <strong>mêmes mods</strong> de contenu. Les mods purement visuels ou d&#39;optimisation, comme Sodium, peuvent différer. Le plus simple consiste à partager l&#39;instance avec vos amis (voir <a href="./jouer-ensemble">Jouer ensemble</a>) ou au format <code>.kpack</code> (voir <a href="./modpacks">Modpacks</a>).</p></div><p>Les serveurs exigeant un compte Microsoft (comme Hypixel) ne sont pas accessibles. Kodus fonctionne en réseau local et sur les serveurs configurés en mode hors ligne (<code>online-mode=false</code>).</p>',10)])])}const g=o(t,[["render",u]]);export{p as __pageData,g as default};
